SELECT data.commit.collection AS event, COUNT(*) AS cnt FROM bluesky GROUP BY event ORDER BY cnt DESC LIMIT 10000 OPTION max_matches=10000;
SELECT data.commit.collection AS event, TO_STRING(data.did) AS d, COUNT(*) AS cnt, COUNT(DISTINCT d) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 10000 OPTION max_matches=10000, distinct_precision_threshold=0;
SELECT data.commit.collection AS event, IDIV(BIGINT(data.time_us), 3600000000) % 24 AS hour_of_day, COUNT(*) AS cnt FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day ASC, event ASC LIMIT 1000;
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS first_post_ts FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT data.did AS user_id, IDIV(MAX(BIGINT(data.time_us)) - MIN(BIGINT(data.time_us)), 1000) AS activity_span FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
